window.AUTH=window.AUTH||{};window.AUTH["17-1594"]={"d":"17-1594","id":"2018/17-1594","n":"Return Mail, Inc. v. United States Postal Service","briefs":[{"k":"petitioner","label":"Brief of petitioner Return Mail, Inc.","date":"2018-12-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1594/74700/20181210165659990_2018.12.10%20Return%20Mail%20v.%20USPS%20-%20No.%2017-1594%20-%20Brief%20for%20Petitioner.pdf","side":"pet","n":50},{"k":"respondent","label":"Brief of respondents United States Postal Service, et al.","date":"2019-01-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-1594/78942/20190109184500100_17-1594bsUnitedStates.pdf","side":"res","n":114},{"k":"reply","label":"Reply of petitioner Return Mail, Inc.","date":"2019-02-08","url":"https://www.supremecourt.gov/DocketPDF/17/17-1594/87594/20190208111254493_2019.02.08%20RMI%20Reply%20Brief.pdf","side":"pet","n":63}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1594_1an2.pdf","tr":true,"items":[{"t":"case","label":"Alice Corp. v. CLS Bank International","cite":"573 U.S. 208","y":2014,"id":"2013/13-298","sc":1,"op":1,"sum":"The Court found that patent laws should not place restraints on abstract ideas that form the \"building blocks of human ingenuity.\"","sumSrc":"Oyez","by":{"0":"11","1":"12, 13"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"sum":"Section 406 of the Act does not authorize the imposition of a special parole term even though that sanction is included within the penalty provision of the target offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","2":"20"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"134 S. Ct. 2751","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Cannon v. University of Chicago","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"sum":"Petitioner may maintain her lawsuit, despite the absence of any express authorization for it in Title IX.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"City of Arlington v. FCC","cite":"569 U.S. 290","y":2013,"id":"2012/11-1545","sc":1,"sum":"The Court found that the courts must apply the Chevron doctrine and defer to an agency's interpretation of its jurisdiction when that jurisdiction is called into question.","sumSrc":"Oyez","by":{"0":"39","2":"12"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Crozier v. Fried. Krupp Aktiengesellschaft","cite":"224 U.S. 290","y":1912,"id":"scdb/1911-210","sc":1,"sum":"Prior to the passage of the act of June 25, 1910, 36 Stat. 851, c. 423, a patentee, whose patent was infringed by an officer of the United States, could not sue the United States unless a contract to pay was implied; and the object of the statute is to afford a remedy under circumstances where no contract can be implied, but where the property rights of the inventor have been appropriated by an officer of the United …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28","1":"4, 27"}},{"t":"case","label":"Cuozzo Speed Technologies, LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"op":2,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"6, 8, 24, 36","1":"7, 30"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Dorsey v. United States","cite":"567 U.S. 260","y":2012,"id":"2011/11-5683","sc":1,"sum":"The Court held that criminals who had committed drug crimes before the passage of the Fair Sentencing Act of 2010 but were sentenced after its passage were entitled to the sentencing provisions laid out in the Act.","sumSrc":"Oyez","by":{"0":"16, 22"}},{"t":"case","label":"Federal Crop Insurance Corp. v. Merrill","cite":"332 U.S. 380","y":1947,"id":"scdb/1947-002","sc":1,"sum":"The Corporation is not liable for the loss on the reseeded acreage.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Federal Express Corp. v. United States Postal Service","cite":"151 F.3d 536","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/536/","by":{"0":"32"}},{"t":"case","label":"Florida Prepaid Postsecondary Education Expense Board v. College Savings Bank","cite":"527 U.S. 627","y":1999,"id":"1998/98-531","sc":1,"op":1,"ar":1,"sum":"The Court reasoned that although the Fourteenth Amendment authorizes Congress to pass \"appropriate legislation\" to protect parties from being deprived of property without due process, this in itself does not permit the abrogation of state sovereign immunity.","sumSrc":"Oyez","by":{"0":"29","1":"24","2":"4"}},{"t":"case","label":"Global Mail Ltd. v. United States Postal Service","cite":"142 F.3d 208","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/142/208/","sum":"Concluding that “agencies [like the Postal Service] whose sovereign immunity has been independently waived . . . are ‘juristic persons’ under the terms of the Lanham Act”.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"sum":"Petitioners (collectively Gustafson), the sole shareholders of Alloyd, Inc., sold substantially all of its stock to respondents and other buyers in a private sale agreement. The purchase price included a payment reflecting an estimated increase in the company's net worth from the end of the previous year through the closing, since hard financial data were unavailable. The contract provided that if a year-end audit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Heckler v. Community Health Services of Crawford County, Inc.","cite":"467 U.S. 51","y":1984,"id":"1983/83-56","sc":1,"sum":"Under the Medicare program, providers of health care services are reimbursed for the reasonable cost of services rendered to Medicare beneficiaries and are required to submit annual cost reports which are audited to determine actual costs. The Secretary of Health and Human Services (Secretary) may reopen any reimbursement determination within a 3-year period and make appropriate adjustments. Respondent nonprofit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Hubbard v. United States","cite":"514 U.S. 695","y":1995,"id":"1994/94-172","sc":1,"sum":"The judgment is reversed in part. 16 F. 3d 694, reversed in part. JUSTICE STEVENS delivered the opinion of the Court with respect to Parts I, II, III, and VI, concluding that, because a federal court is neither a \"department\" nor an \"agency\" within § 1001's meaning, the statute does not apply to false statements made in judicial proceedings. Pp. 699-708, 715.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"International Primate Protection League v. Administrators of Tulane Education Fund","cite":"500 U.S. 72","y":1991,"id":"1990/90-89","sc":1,"op":3,"sum":"Concluding that the National Institutes of Health was not authorized to remove an action as a “ ‘person acting under [a federal]’ officer” pursuant to 28 U. S. C. §1442(a)(1).","sumSrc":"opinion","by":{"0":"39","2":"9, 11"}},{"t":"case","label":"Louisiana Public Service Commission v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","2":"12"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"op":3,"sum":"Holding that §282’s presumption of validity in litigation imposes a clear and convincing evidence standard on defendants seeking to prove invalidity.","sumSrc":"opinion","by":{"0":"36","1":"5, 32"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Monell v. N.Y.C. Dep’t of Social Servs.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Montana v. United States","cite":"440 U.S. 147","y":1979,"id":"1978/77-1134","sc":1,"sum":"The United States is collaterally estopped from challenging the prior judgment of the Montana Supreme Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"41"}},{"t":"case","label":"Motorola, Inc. v. United States","cite":"729 F.2d 765","y":1984,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/729/765/","by":{"0":"29","1":"5","2":"4, 22"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"sum":"The Court held that FERC properly construed its statutory authority.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Ngiraingas v. Sanchez","cite":"495 U.S. 182","y":1990,"id":"1989/88-1281","sc":1,"sum":"Neither the Territory of Guam nor its officers acting in their official capacities are \"persons\" under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Office of Personnel Management v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"18, 40, 41, 42","1":"42"}},{"t":"case","label":"Oil States Energy Services, LLC v. Greene’s Energy Group, LLC","cite":"138 S. Ct. 1365","y":2018,"id":"2017/16-712","sc":1,"sum":"The Court decided that inter partes review, which authorizes the United States Patent and Trademark Office to reconsider and cancel an already-issued patent claim under 35 U.S.C. §§ 311-391, does not violate Article III or the Seventh Amendment of the Constitution.","sumSrc":"Oyez","by":{"0":"23, 24","1":"6, 8"}},{"t":"case","label":"Rowland v. California Men’s Colony","cite":"506 U.S. 194","y":1993,"id":"1992/91-1188","sc":1,"op":2,"sum":"In a suit filed in the District Court against petitioner state correctional officers, respondent, a representative association of inmates in a California prison, sought leave to proceed in forma pauperis under 28 U. S. C. § 1915(a), which permits litigation without prepayment of fees, costs, or security \"by a person who makes affidavit that he is unable to pay.\" The court denied the motion for an inadequate showing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"SAS Institute Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"ar":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"0":"5, 6, 23, 28"}},{"t":"case","label":"Shaw Industries Group, Inc. v. Automated Creel Systems, Inc.","cite":"817 F.3d 1293","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/817/1293/","sum":"Describing estoppel in IPRs as governed by “statutory estoppel provisions”.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"0":"42, 43"}},{"t":"case","label":"U.S. Postal Service v. Flamingo Indus. (USA) Ltd.","cite":"540 U.S. 736","y":2004,"id":"2003/02-1290","sc":1,"sum":"The Court held that the U.S. Postal Service cannot be sued under antitrust laws. The Court acknowledged the Postal Reorganization Act may waive the Postal Service's immunity from suit. However, federal antitrust laws (the Sherman Act, for example) do not allow the federal government - of which the Postal Service is a part - to be sued.","sumSrc":"Oyez","by":{"0":"passim","2":"23"}},{"t":"case","label":"United States v. Cleveland Indians Baseball Co.","cite":"532 U.S. 200","y":2001,"id":"2000/00-203","sc":1,"sum":"The Court held that back wages are subject to FICA and FUTA taxes by reference to the year the wages are in fact paid. \"Although the regulations, like the statute, do not specifically address backpay, the Internal Revenue Service has consistently interpreted them to require taxation of back wages according to the year the wages are actually paid, regardless of when those wages were earned or should have been paid,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"0":"17, 31"}},{"t":"case","label":"United States v. Cooper Corp.","cite":"312 U.S. 600","y":1941,"id":"scdb/1940-054","sc":1,"op":7,"sum":"1. While the United States is a juristic person in the sense that it can sue upon its contracts or in vindication of its property rights, the term \"person\" does not include the sovereign, in common usage, nor, ordinarily, when employed in statutes.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 26","1":"32, 37, 38","2":"5, 9, 10, 11"}},{"t":"case","label":"United States v. Fox","cite":"94 U.S. 315","y":1876,"id":"scdb/1876-171","sc":1,"op":2,"sum":"Holding that the Federal Government was not a “ ‘person capable by law of holding real estate,’ ” absent “an express definition to that effect”.","sumSrc":"opinion","by":{"0":"passim","1":"37","2":"10, 11"}},{"t":"case","label":"United States v. Mendoza","cite":"464 U.S. 154","y":1984,"id":"1983/82-849","sc":1,"ar":1,"sum":"The United States may not be collaterally estopped on an issue such as the one involved here, adjudicated against it in an earlier lawsuit brought by a different party.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","1":"41, 42"}},{"t":"case","label":"United States v. Q Int’l Courier, Inc.","cite":"131 F.3d 770","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/131/770/","by":{"0":"33"}},{"t":"case","label":"United States v. Stauffer Chemical Co.","cite":"464 U.S. 165","y":1983,"id":"1983/82-1448","sc":1,"sum":"The Court held that the EPA's case against Stauffer was precluded by the doctrine of collateral estoppell.","sumSrc":"Oyez","by":{"0":"43","1":"41, 42"}},{"t":"case","label":"United States v. United Mine Workers of America","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"op":3,"sum":"Reasoning that Congress’ express inclusion of partnerships and corporations in §1 implies that Congress did not intend to include the Government.","sumSrc":"opinion","by":{"0":"22, 25","1":"33, 35","2":"7, 11"}},{"t":"case","label":"Utah Power & Light Co. v. United States","cite":"243 U.S. 389","y":1917,"id":"scdb/1916-144","sc":1,"sum":"The power to regulate the use of the lands of the United States, and to prescribe the conditions upon which rights in them may be acquired by others,' is vested exclusively in Congress.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Utility Air Regulatory Group v. EPA","cite":"134 S. Ct. 2427","y":2014,"id":"2013/12-1146","sc":1,"op":2,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Vermont Agency of Natural Resources v. U.S. ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":4,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"0":"passim","1":"32, 33","2":"1, 2, 8"}},{"t":"case","label":"Will v. Michigan Department of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22, 25","1":"33","2":"7, 9, 11"}},{"t":"case","label":"Wilson v. Omaha Indian Tribe","cite":"442 U.S. 653","y":1979,"id":"1978/78-160","sc":1,"sum":"Pursuant to an 1854 treaty,-the reservation of the Omaha Indian Tribe (Tribe) was established in the Territory of Nebraska on the west bank of the Missouri River, with the eastern boundary being fixed as the center of the river's main channel. In 1867, a General Land Office survey established that certain land was included in the reservation but since then the river has changed course several times, leaving most of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 25","1":"32","2":"7, 11"}},{"t":"case","label":"Zoltek Corp. v. United States","cite":"672 F.3d 1309","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/672/1309/","by":{"0":"29"}},{"t":"case","label":"B & B Hardware, Inc. v. Hargis Indus., Inc.","cite":"135 S. Ct. 1293","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"1":"41","2":"20"}},{"t":"case","label":"Bilski v. Kappos","cite":"561 U.S. 593","y":2010,"id":"2009/08-964","sc":1,"sum":"The Court held that the \"machine-or-transformation\" test adopted by the Patent and Trademark Office (PTO) was a legal means for determining patent eligibility.","sumSrc":"Oyez","by":{"1":"30, 31"}},{"t":"case","label":"(III) Cases—Continued: Burwell v. Hobby Lobby Stores, Inc.","cite":"134 S. Ct. 2751","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2751/","sc":1,"by":{"1":"22"}},{"t":"case","label":"Decca Ltd. v. United States","cite":"640 F.2d 1156","y":1980,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/640/1156/","by":{"1":"5"}},{"t":"case","label":"Director, Office of Workers’ Comp. Programs v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"op":3,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"op":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Georgia v. Evans","cite":"316 U.S. 159","y":1942,"id":"scdb/1941-097","sc":1,"ar":2,"sum":"A State is a \"person\" within the meaning of § 7 of the Sherman Act and entitled thereby to sue for treble damages when, as a purchaser of asphalt, it is injured by a combination suppressing competition and fixing prices of that commodity in interstate commerce. United States v. Cooper Corp., 312 U. S. 600, distinguished. P. 162. 123 F. 2d 57, reversed. Courts of other states have considered similar questions. Henry …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 34","2":"12, 13"}},{"t":"case","label":"Halo Elecs., Inc. v. Pulse Elecs., Inc.","cite":"136 S. Ct. 1923","y":2016,"id":"2015/14-1513","sc":1,"op":1,"sum":"The Court determined that the rigid two-part test is not necessary for determining whether a patentee is eligible for enhanced damages under 35 U.S.C §284.","sumSrc":"Oyez","by":{"1":"5, 6"}},{"t":"case","label":"Hitkansut LLC v. United States","cite":"130 Fed. Cl. 353","y":2017,"url":"https://www.courtlistener.com/c/Fed.%20Cl./130/353/","by":{"1":"5, 32"}},{"t":"case","label":"INS v. Hibi","cite":"414 U.S. 5","y":1973,"id":"1973/72-1652","sc":1,"sum":"Neither the failure tb\"fully publicize the rights to 'naturalization afforded by the Nationality Act of 1940 to noncitizens who served in the United States Armed Forces during World War II nor the failure to have an authorized naturalization representative stationed in the Philippine Islands during the time such rights were available, estopped the Government from relying on the fact that the deadline for filing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Inyo Cnty. v. Paiute-Shoshone Indians of the Bishop Cmty. of the Bishop Colony","cite":"538 U.S. 701","y":2003,"id":"2002/02-281","sc":1,"sum":"The Court held that, in the situation presented, the Tribe does not qualify as a \"person\" who may sue under section 1983 to vindicate the sovereign right it here claims.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"James v. Campbell","cite":"104 U.S. 356","y":1882,"id":"scdb/1881-061","sc":1,"sum":"The facts are fully stated in the opinion of the court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26, 27, 37"}},{"t":"case","label":"KSR Int’l Co. v. Teleflex Inc.","cite":"550 U.S. 398","y":2007,"id":"2006/04-1350","sc":1,"sum":"The Court ruled unanimously that the Federal Circuit \"analyzed the issue in a narrow, rigid manner inconsistent with [Section 103(a)] and our precedents.\" Justice Anthony Kennedy wrote the opinion for the Court, which ruled in favor of KSR and reversed the Court of Appeals.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Lamson v. United States","cite":"117 Fed. Cl. 755","y":2014,"url":"https://www.courtlistener.com/c/Fed.%20Cl./117/755/","op":1,"sum":"Noting that the Government may “avail itself of any defense that is available to a private party in an infringement action”.","sumSrc":"opinion","by":{"1":"5"}},{"t":"case","label":"Leesona Corp. v. United States","cite":"599 F.2d 958","y":1979,"url":"https://www.courtlistener.com/c/F.2d/599/958/","by":{"1":"5"}},{"t":"case","label":"Lemelson v. United States","cite":"752 F.2d 1538","y":1985,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/752/1538/","by":{"1":"5"}},{"t":"case","label":"Loeffler v. Frank","cite":"486 U.S. 549","y":1988,"id":"1987/86-1431","sc":1,"sum":"Prejudgment interest may be awarded in a suit against the Postal Service brought under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Marine Polymer Techs., Inc. v. HemCom, Inc.","cite":"672 F.3d 1350","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/672/1350/","by":{"1":"21"}},{"t":"case","label":"Pfizer Inc. v. Government of India","cite":"434 U.S. 308","y":1978,"id":"1977/76-749","sc":1,"ar":3,"sum":"A foreign nation otherwise entitled to sue in the courts of this country held to be a \"person\" within the meaning of §4 of the Clayton Act and thus to be entitled to sue for treble damages under the federal antitrust laws to the same extent as any other plaintiff.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 32, 34, 39","2":"13"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"op":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"1":"21","2":"6"}},{"t":"case","label":"Robers v. United States","cite":"134 S. Ct. 1854","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"1":"21","2":"2"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"1":"22","2":"8"}},{"t":"case","label":"Schillinger v. United States","cite":"155 U.S. 163","y":1894,"id":"scdb/1894-019","sc":1,"sum":"The United States cannot be sued in their courts without their consent.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"27, 37"}},{"t":"case","label":"Stanley v. Schwalby","cite":"147 U.S. 508","y":1893,"id":"scdb/1892-098","sc":1,"sum":"For purposes of jurisdiction there is no distinction between suits against the government directly, and suits against its property.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"35, 39","2":"12"}},{"t":"case","label":"State Street Bank & Trust Co. v. Signature Financial Grp., Inc.","cite":"149 F.3d 1368","y":1998,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/149/1368/","by":{"1":"30"}},{"t":"case","label":"United States v. ICC","cite":"337 U.S. 426","y":1949,"id":"scdb/1948-095","sc":1,"sum":"The United States, as a shipper, having undertaken to provide wharfage and handling services at certain. piers, requested the railroads to make an allowance for expenses thus incurred, since the shipside rates allegedly included charges for wharfage and handling services. The railroads refused to make an allowance and'to perform the services. The United States thereupon filed with the Interstate Commerce Commission …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 36","2":"13, 14"}},{"t":"case","label":"United States Dep’t of Health & Human Servs. v. Mylan Pharm. Inc.","cite":"2011 WL 13238650","y":2011,"court":"D.N.J. July 13","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 96-517","url":"https://www.govinfo.gov/link/statute/94/3015","by":{"1":"6"}},{"t":"usc","label":"35 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/35/301","stext":{"head":"§301. Citation of prior art and written statements","paras":[[0,"(a) In General.—Any person at any time may cite to the Office in writing—"],[1,"(1) prior art consisting of patents or printed publications which that person believes to have a bearing on the patentability of any claim of a particular patent; or"],[1,"(2) statements of the patent owner filed in a proceeding before a Federal court or the Office in which the patent owner took a position on the scope of any claim of a particular patent."],[0,"(b) Official File.—If the person citing prior art or written statements pursuant to subsection (a) explains in writing the pertinence and manner of applying the prior art or written statements to at least 1 claim of the patent, the citation of the prior art or written statements and the explanation thereof shall become a part of the official file of the patent."],[0,"(c) Additional Information.—A party that submits a written statement pursuant to subsection (a)(2) shall include any other documents, pleadings, or evidence from the proceeding in which the statement was filed that addresses the written statement."],[0,"(d) Limitations.—A written statement submitted pursuant to subsection (a)(2), and additional information submitted pursuant to subsection (c), shall not be considered by the Office for any purpose other than to determine the proper meaning of a patent claim in a proceeding that is ordered or instituted pursuant to section 304, 314, or 324. If any such written statement or additional information is subject to an applicable protective order, such statement or information shall be redacted to exclude information that is subject to that order."],[0,"(e) Confidentiality.—Upon the written request of the person citing prior art or written statements pursuant to subsection (a), that person's identity shall be excluded from the patent file and kept confidential."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/301?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§301. Citation of prior art and written statements","tname":"Patents","by":{"1":"6, 27, 28, 11"}},{"t":"usc","label":"35 U.S.C. § 302","url":"https://www.law.cornell.edu/uscode/text/35/302","subs":["(2006)"],"stext":{"head":"§302. Request for reexamination","paras":[[0,"Any person at any time may file a request for reexamination by the Office of any claim of a patent on the basis of any prior art cited under the provisions of section 301. The request must be in writing and must be accompanied by payment of a reexamination fee established by the Director pursuant to the provisions of section 41. The request must set forth the pertinency and manner of applying cited prior art to every claim for which reexamination is requested. Unless the requesting person is the owner of the patent, the Director promptly will send a copy of the request to the owner of record of the patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/302?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§302. Request for reexamination","tname":"Patents","by":{"1":"6, 27, 28, 11"}},{"t":"usc","label":"35 U.S.C. § 303","url":"https://www.law.cornell.edu/uscode/text/35/303","subs":["(a)"],"ar":1,"by":{"1":"6","2":"13"}},{"t":"usc","label":"35 U.S.C. § 200","url":"https://www.law.cornell.edu/uscode/text/35/200","by":{"1":"3"}},{"t":"usc","label":"35 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/35/202","subs":["(c)(1)"],"by":{"1":"3"}},{"t":"usc","label":"35 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/35/207","subs":["(a)(1)","(a)(2)"],"stext":{"head":"§207. Domestic and foreign protection of federally owned inventions","paras":[[0,"(a) Each Federal agency is authorized to—"],[1,"(1) apply for, obtain, and maintain patents or other forms of protection in the United States and in foreign countries on inventions in which the Federal Government owns a right, title, or interest;"],[1,"(2) grant nonexclusive, exclusive, or partially exclusive licenses under federally owned inventions, royalty-free or for royalties or other consideration, and on such terms and conditions, including the grant to the licensee of the right of enforcement pursuant to the provisions of chapter 29 as determined appropriate in the public interest;"],[1,"(3) undertake all other suitable and necessary steps to protect and administer rights to federally owned inventions on behalf of the Federal Government either directly or through contract, including acquiring rights for and administering royalties to the Federal Government in any invention, but only to the extent the party from whom the rights are acquired voluntarily enters into the transaction, to facilitate the licensing of a federally owned invention; and"],[1,"(4) transfer custody and administration, in whole or in part, to another Federal agency, of the right, title, or interest in any federally owned invention."],[0,"(b) For the purpose of assuring the effective management of Government-owned inventions, the Secretary of Commerce is authorized to—"],[1,"(1) assist Federal agency efforts to promote the licensing and utilization of Government-owned inventions;"],[1,"(2) assist Federal agencies in seeking protection and maintaining inventions in foreign countries, including the payment of fees and costs connected therewith; and"],[1,"(3) consult with and advise Federal agencies as to areas of science and technology research and development with potential for commercial utilization."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/207?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":3,"head":"§207. Domestic and foreign protection of federally owned inventions","tname":"Patents","by":{"1":"4, 4, 4","2":"3, 15"}},{"t":"usc","label":"5 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/5/1001","by":{"1":"35"}},{"t":"usc","label":"5 U.S.C. § 1009","url":"https://www.law.cornell.edu/uscode/text/5/1009","subs":["(a)(1946)"],"by":{"1":"36"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"1":"35","2":"1, 2, 7, 8"}},{"t":"usc","label":"49 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/49/1","by":{"1":"35"}},{"t":"usc","label":"49 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/49/9","subs":["(1946)"],"by":{"1":"36","2":"7"}},{"t":"law","label":"Leahy-Smith America Invents Act, Pub. L. No. 112-29","url":"https://www.govinfo.gov/link/plaw/112/public/29","by":{"1":"8"}},{"t":"usc","label":"35 U.S.C. § 311","url":"https://www.law.cornell.edu/uscode/text/35/311","subs":["(2000)","(a)(2000)","(a)","(b)"],"stext":{"head":"§311. Inter partes review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute an inter partes review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the review."],[0,"(b) Scope.—A petitioner in an inter partes review may request to cancel as unpatentable 1 or more claims of a patent only on a ground that could be raised under section 102 or 103 and only on the basis of prior art consisting of patents or printed publications."],[0,"(c) Filing Deadline.—A petition for inter partes review shall be filed after the later of either—"],[1,"(1) the date that is 9 months after the grant of a patent; or"],[1,"(2) if a post-grant review is instituted under chapter 32, the date of the termination of such post-grant review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/311?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§311. Inter partes review","tname":"Patents","by":{"1":"7, 25, 9, 22, 8, 22, 8, 22"}},{"t":"usc","label":"35 U.S.C. § 312","url":"https://www.law.cornell.edu/uscode/text/35/312","subs":["(a)(2000)"],"by":{"1":"25"}},{"t":"usc","label":"35 U.S.C. § 313","url":"https://www.law.cornell.edu/uscode/text/35/313","subs":["(2000)"],"by":{"1":"25, 8, 22"}},{"t":"usc","label":"35 U.S.C. § 315","url":"https://www.law.cornell.edu/uscode/text/35/315","subs":["(c)(2000)","(e)","(e)(1)","(e)(2)"],"stext":{"head":"§315. Relation to other proceedings or actions","paras":[[0,"(a) Infringer's Civil Action.—"],[1,"(1) Inter partes review barred by civil action.—An inter partes review may not be instituted if, before the date on which the petition for such a review is filed, the petitioner or real party in interest filed a civil action challenging the validity of a claim of the patent."],[1,"(2) Stay of civil action.—If the petitioner or real party in interest files a civil action challenging the validity of a claim of the patent on or after the date on which the petitioner files a petition for inter partes review of the patent, that civil action shall be automatically stayed until either—"],[2,"(A) the patent owner moves the court to lift the stay;"],[2,"(B) the patent owner files a civil action or counterclaim alleging that the petitioner or real party in interest has infringed the patent; or"],[2,"(C) the petitioner or real party in interest moves the court to dismiss the civil action."],[1,"(3) Treatment of counterclaim.—A counterclaim challenging the validity of a claim of a patent does not constitute a civil action challenging the validity of a claim of a patent for purposes of this subsection."],[0,"(b) Patent Owner's Action.—An inter partes review may not be instituted if the petition requesting the proceeding is filed more than 1 year after the date on which the petitioner, real party in interest, or privy of the petitioner is served with a complaint alleging infringement of the patent. The time limitation set forth in the preceding sentence shall not apply to a request for joinder under subsection (c)."],[0,"(c) Joinder.—If the Director institutes an inter partes review, the Director, in his or her discretion, may join as a party to that inter partes review any person who properly files a petition under section 311 that the Director, after receiving a preliminary response under section 313 or the expiration of the time for filing such a response, determines warrants the institution of an inter partes review under section 314."],[0,"(d) Multiple Proceedings.—Notwithstanding sections 135(a), 251, and 252, and chapter 30, during the pendency of an inter partes review, if another proceeding or matter involving the patent is before the Office, the Director may determine the manner in which the inter partes review or other proceeding or matter may proceed, including providing for stay, transfer, consolidation, or termination of any such matter or proceeding."],[0,"(e) Estoppel.—"],[1,"(1) Proceedings before the office.—The petitioner in an inter partes review of a claim in a patent under this chapter that results in a final written decision under section 318(a), or the real party in interest or privy of the petitioner, may not request or maintain a proceeding before the Office with respect to that claim on any ground that the petitioner raised or reasonably could have raised during that inter partes review."],[1,"(2) Civil actions and other proceedings.—The petitioner in an inter partes review of a claim in a patent under this chapter that results in a final written decision under section 318(a), or the real party in interest or privy of the petitioner, may not assert either in a civil action arising in whole or in part under section 1338 of title 28 or in a proceeding before the International Trade Commission under section 337 of the Tariff Act of 1930 that the claim is invalid on any ground that the petitioner raised or reasonably could have raised during that inter partes review."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/315?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§315. Relation to other proceedings or actions","tname":"Patents","by":{"1":"25, 8, 22, 8, 22, 8, 22","2":"21"}},{"t":"usc","label":"35 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/35/1","op":1,"by":{"1":"2"}},{"t":"usc","label":"35 U.S.C. § 6","url":"https://www.law.cornell.edu/uscode/text/35/6","subs":["(a)"],"stext":{"head":"§6. Patent Trial and Appeal Board","paras":[[0,"(a) In General.—There shall be in the Office a Patent Trial and Appeal Board. The Director, the Deputy Director, the Commissioner for Patents, the Commissioner for Trademarks, and the administrative patent judges shall constitute the Patent Trial and Appeal Board. The administrative patent judges shall be persons of competent legal knowledge and scientific ability who are appointed by the Secretary, in consultation with the Director. Any reference in any Federal law, Executive order, rule, regulation, or delegation of authority, or any document of or pertaining to the Board of Patent Appeals and Interferences is deemed to refer to the Patent Trial and Appeal Board."],[0,"(b) Duties.—The Patent Trial and Appeal Board shall—"],[1,"(1) on written appeal of an applicant, review adverse decisions of examiners upon applications for patents pursuant to section 134(a);"],[1,"(2) review appeals of reexaminations pursuant to section 134(b);"],[1,"(3) conduct derivation proceedings pursuant to section 135; and"],[1,"(4) conduct inter partes reviews and post-grant reviews pursuant to chapters 31 and 32."],[0,"(c) 3-Member Panels.—Each appeal, derivation proceeding, post-grant review, and inter partes review shall be heard by at least 3 members of the Patent Trial and Appeal Board, who shall be designated by the Director. Only the Patent Trial and Appeal Board may grant rehearings."],[0,"(d) Treatment of Prior Appointments.—The Secretary of Commerce may, in the Secretary's discretion, deem the appointment of an administrative patent judge who, before the date of the enactment of this subsection, held office pursuant to an appointment by the Director to take effect on the date on which the Director initially appointed the administrative patent judge. It shall be a defense to a challenge to the appointment of an administrative patent judge on the basis of the judge's having been originally appointed by the Director that the administrative patent judge so appointed was acting as a de facto officer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/6?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6. Patent Trial and Appeal Board","tname":"Patents","by":{"1":"24","2":"6"}},{"t":"usc","label":"35 U.S.C. § 100","url":"https://www.law.cornell.edu/uscode/text/35/100","subs":["(h)"],"stext":{"head":"§100. Definitions","paras":[[0,"When used in this title unless the context otherwise indicates—"],[0,"(a) The term \"invention\" means invention or discovery."],[0,"(b) The term \"process\" means process, art or method, and includes a new use of a known process, machine, manufacture, composition of matter, or material."],[0,"(c) The terms \"United States\" and \"this country\" mean the United States of America, its territories and possessions."],[0,"(d) The word \"patentee\" includes not only the patentee to whom the patent was issued but also the successors in title to the patentee."],[0,"(e) The term \"third-party requester\" means a person requesting ex parte reexamination under section 302 who is not the patent owner."],[0,"(f) The term \"inventor\" means the individual or, if a joint invention, the individuals collectively who invented or discovered the subject matter of the invention."],[0,"(g) The terms \"joint inventor\" and \"coinventor\" mean any 1 of the individuals who invented or discovered the subject matter of a joint invention."],[0,"(h) The term \"joint research agreement\" means a written contract, grant, or cooperative agreement entered into by 2 or more persons or entities for the performance of experimental, developmental, or research work in the field of the claimed invention."],[0,"(i)(1) The term \"effective filing date\" for a claimed invention in a patent or application for patent means—"],[1,"(A) if subparagraph (B) does not apply, the actual filing date of the patent or the application for the patent containing a claim to the invention; or"],[1,"(B) the filing date of the earliest application for which the patent or application is entitled, as to such invention, to a right of priority under section 119, 365(a), 365(b), 386(a), or 386(b) or to the benefit of an earlier filing date under section 120, 121, 365(c), or 386(c)."],[0,"(2) The effective filing date for a claimed invention in an application for reissue or reissued patent shall be determined by deeming the claim to the invention to have been contained in the patent for which reissue was sought."],[0,"(j) The term \"claimed invention\" means the subject matter defined by a claim in a patent or an application for a patent."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/100?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§100. Definitions","tname":"Patents","by":{"1":"20","2":"6"}},{"t":"usc","label":"35 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/35/101","by":{"1":"2, 10, 2"}},{"t":"usc","label":"35 U.S.C. § 102","url":"https://www.law.cornell.edu/uscode/text/35/102","subs":["(a)","(a)(1)","(b)(2)(C)"],"by":{"1":"2, 14, 18, 19, 20, 21, 2, 2, 2","2":"3"}},{"t":"usc","label":"35 U.S.C. § 103","url":"https://www.law.cornell.edu/uscode/text/35/103","by":{"1":"2"}},{"t":"usc","label":"35 U.S.C. § 118","url":"https://www.law.cornell.edu/uscode/text/35/118","stext":{"head":"§118. Filing by other than inventor","paras":[[0,"A person to whom the inventor has assigned or is under an obligation to assign the invention may make an application for patent. A person who otherwise shows sufficient proprietary interest in the matter may make an application for patent on behalf of and as agent for the inventor on proof of the pertinent facts and a showing that such action is appropriate to preserve the rights of the parties. If the Director grants a patent on an application filed under this section by a person other than the inventor, the patent shall be granted to the real party in interest and upon such notice to the inventor as the Director considers to be sufficient."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/118?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§118. Filing by other than inventor","tname":"Patents","by":{"1":"19, 20, 21","2":"3"}},{"t":"usc","label":"35 U.S.C. § 119","url":"https://www.law.cornell.edu/uscode/text/35/119","subs":["(a)"],"stext":{"head":"§119. Benefit of earlier filing date; right of priority","paras":[[0,"(a) An application for patent for an invention filed in this country by any person who has, or whose legal representatives or assigns have, previously regularly filed an application for a patent for the same invention in a foreign country which affords similar privileges in the case of applications filed in the United States or to citizens of the United States, or in a WTO member country, shall have the same effect as the same application would have if filed in this country on the date on which the application for patent for the same invention was first filed in such foreign country, if the application in this country is filed within 12 months from the earliest date on which such foreign application was filed. The Director may prescribe regulations, including the requirement for payment of the fee specified in section 41(a)(7), pursuant to which the 12-month period set forth in this subsection may be extended by an additional 2 months if the delay in filing the application in this country within the 12-month period was unintentional."],[0,"(b)(1) No application for patent shall be entitled to this right of priority unless a claim is filed in the Patent and Trademark Office, identifying the foreign application by specifying the application number on that foreign application, the intellectual property authority or country in or for which the application was filed, and the date of filing the application, at such time during the pendency of the application as required by the Director."],[0,"(2) The Director may consider the failure of the applicant to file a timely claim for priority as a waiver of any such claim. The Director may establish procedures, including the requirement for payment of the fee specified in section 41(a)(7), to accept an unintentionally delayed claim under this section."],[0,"(3) The Director may require a certified copy of the original foreign application, specification, and drawings upon which it is based, a translation if not in the English language, and such other information as the Director considers necessary. Any such certification shall be made by the foreign intellectual property authority in which the foreign application was filed and show the date of the application and of the filing of the specification and other papers."],[0,"(c) In like manner and subject to the same conditions and requirements, the right provided in this section may be based upon a subsequent regularly filed application in the same foreign country instead of the first filed foreign application, provided that any foreign application filed prior to such subsequent application has been withdrawn, abandoned, or otherwise disposed of, without having been laid open to public inspection and without leaving any rights outstanding, and has not served, nor thereafter shall serve, as a basis for claiming a right of priority."],[0,"(d) Applications for inventors' certificates filed in a foreign country in which applicants have a right to apply, at their discretion, either for a patent or for an inventor's certificate shall be treated in this country in the same manner and have the same effect for purpose of the right of priority under this section as applications for patents, subject to the same conditions and requirements of this section as apply to applications for patents, provided such applicants are entitled to the benefits of the Stockholm Revision of the Paris Convention at the time of such filing."],[0,"(e)(1) An application for patent filed under section 111(a) or section 363 for an invention disclosed in the manner provided by section 112(a) (other than the requirement to disclose the best mode) in a provisional application filed under section 111(b), by an inventor or inventors named in the provisional application, shall have the same effect, as to such invention, as though filed on the date of the provisional application filed under section 111(b), if the application for patent filed under section 111(a) or section 363 is filed not later than 12 months after the date on which the provisional application was filed and if it contains or is amended to contain a specific reference to the provisional application. The Director may prescribe regulations, including the requirement for payment of the fee specified in section 41(a)(7), pursuant to which the 12-month period set forth in this subsection may be extended by an additional 2 months if the delay in filing the application under section 111(a) or section 363 within the 12-month period was unintentional. No application shall be entitled to the benefit of an earlier filed provisional application under this subsection unless an amendment containing the specific reference to the earlier filed provisional application is submitted at such time during the pendency of the application as required by the Director. The Director may consider the failure to submit such an amendment within that time period as a waiver of any benefit under this subsection. The Director may establish procedures, including the payment of the fee specified in section 41(a)(7), to accept an unintentionally delayed submission of an amendment under this subsection."],[0,"(2) A provisional application filed under section 111(b) may not be relied upon in any proceeding in the Patent and Trademark Office unless the fee set forth in subparagraph (A) or (C) of section 41(a)(1) has been paid."],[0,"(3) If the day that is 12 months after the filing date of a provisional application falls on a Saturday, Sunday, or Federal holiday within the District of Columbia, the period of pendency of the provisional application shall be extended to the next succeeding secular or business day. For an application for patent filed under section 363 in a Receiving Office other than the Patent and Trademark Office, the 12-month and additional 2-month period set forth in this subsection shall be extended as provided under the treaty and Regulations as defined in section 351."],[0,"(f) Applications for plant breeder's rights filed in a WTO member country (or in a foreign UPOV Contracting Party) shall have the same effect for the purpose of the right of priority under subsections (a) through (c) of this section as applications for patents, subject to the same conditions and requirements of this section as apply to applications for patents."],[0,"(g) As used in this section—"],[1,"(1) the term \"WTO member country\" has the same meaning as the term is defined in section 104(b)(2); and"],[1,"(2) the term \"UPOV Contracting Party\" means a member of the International Convention for the Protection of New Varieties of Plants."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/119?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§119. Benefit of earlier filing date; right of priority","tname":"Patents","by":{"1":"19, 20, 21, 6","2":"3"}},{"t":"usc","label":"35 U.S.C. § 131","url":"https://www.law.cornell.edu/uscode/text/35/131","by":{"1":"6","2":"13"}},{"t":"usc","label":"35 U.S.C. § 209","url":"https://www.law.cornell.edu/uscode/text/35/209","by":{"1":"4"}},{"t":"usc","label":"35 U.S.C. § 252","url":"https://www.law.cornell.edu/uscode/text/35/252","stext":{"head":"§252. Effect of reissue","paras":[[0,"The surrender of the original patent shall take effect upon the issue of the reissued patent, and every reissued patent shall have the same effect and operation in law, on the trial of actions for causes thereafter arising, as if the same had been originally granted in such amended form, but in so far as the claims of the original and reissued patents are substantially identical, such surrender shall not affect any action then pending nor abate any cause of action then existing, and the reissued patent, to the extent that its claims are substantially identical with the original patent, shall constitute a continuation thereof and have effect continuously from the date of the original patent."],[0,"A reissued patent shall not abridge or affect the right of any person or that person's successors in business who, prior to the grant of a reissue, made, purchased, offered to sell, or used within the United States, or imported into the United States, anything patented by the reissued patent, to continue the use of, to offer to sell, or to sell to others to be used, offered for sale, or sold, the specific thing so made, purchased, offered for sale, used, or imported unless the making, using, offering for sale, or selling of such thing infringes a valid claim of the reissued patent which was in the original patent. The court before which such matter is in question may provide for the continued manufacture, use, offer for sale, or sale of the thing made, purchased, offered for sale, used, or imported as specified, or for the manufacture, use, offer for sale, or sale in the United States of which substantial preparation was made before the grant of the reissue, and the court may also provide for the continued practice of any process patented by the reissue that is practiced, or for the practice of which substantial preparation was made, before the grant of the reissue, to the extent and under such terms as the court deems equitable for the protection of investments made or business commenced before the grant of the reissue."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/252?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§252. Effect of reissue","tname":"Patents","by":{"1":"2","2":"3"}},{"t":"usc","label":"35 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/35/271","subs":["(a)"],"stext":{"head":"§271. Infringement of patent","paras":[[0,"(a) Except as otherwise provided in this title, whoever without authority makes, uses, offers to sell, or sells any patented invention, within the United States or imports into the United States any patented invention during the term of the patent therefor, infringes the patent."],[0,"(b) Whoever actively induces infringement of a patent shall be liable as an infringer."],[0,"(c) Whoever offers to sell or sells within the United States or imports into the United States a component of a patented machine, manufacture, combination or composition, or a material or apparatus for use in practicing a patented process, constituting a material part of the invention, knowing the same to be especially made or especially adapted for use in an infringement of such patent, and not a staple article or commodity of commerce suitable for substantial noninfringing use, shall be liable as a contributory infringer."],[0,"(d) No patent owner otherwise entitled to relief for infringement or contributory infringement of a patent shall be denied relief or deemed guilty of misuse or illegal extension of the patent right by reason of his having done one or more of the following: (1) derived revenue from acts which if performed by another without his consent would constitute contributory infringement of the patent; (2) licensed or authorized another to perform acts which if performed without his consent would constitute contributory infringement of the patent; (3) sought to enforce his patent rights against infringement or contributory infringement; (4) refused to license or use any rights to the patent; or (5) conditioned the license of any rights to the patent or the sale of the patented product on the acquisition of a license to rights in another patent or purchase of a separate product, unless, in view of the circumstances, the patent owner has market power in the relevant market for the patent or patented product on which the license or sale is conditioned."],[0,"(e)(1) It shall not be an act of infringement to make, use, offer to sell, or sell within the United States or import into the United States a patented invention (other than a new animal drug or veterinary biological product (as those terms are used in the Federal Food, Drug, and Cosmetic Act and the Act of March 4, 1913) which is primarily manufactured using recombinant DNA, recombinant RNA, hybridoma technology, or other processes involving site specific genetic manipulation techniques) solely for uses reasonably related to the development and submission of information under a Federal law which regulates the manufacture, use, or sale of drugs or veterinary biological products."],[0,"(2) It shall be an act of infringement to submit—"],[1,"(A) an application under section 505(j) of the Federal Food, Drug, and Cosmetic Act or described in section 505(b)(2) of such Act for a drug claimed in a patent or the use of which is claimed in a patent,"],[1,"(B) an application under section 512 of such Act or under the Act of March 4, 1913 (21 U.S.C. 151–158) for a drug or veterinary biological product which is not primarily manufactured using recombinant DNA, recombinant RNA, hybridoma technology, or other processes involving site specific genetic manipulation techniques and which is claimed in a patent or the use of which is claimed in a patent, or"],[1,"(C)(i) with respect to a patent that is identified in the list of patents described in section 351(l)(3) of the Public Health Service Act (including as provided under section 351(l)(7) of such Act), an application seeking approval of a biological product, or"],[1,"(ii) if the applicant for the application fails to provide the application and information required under section 351(l)(2)(A) of such Act, an application seeking approval of a biological product for a patent that could be identified pursuant to section 351(l)(3)(A)(i) of such Act,"],[0,"if the purpose of such submission is to obtain approval under such Act to engage in the commercial manufacture, use, or sale of a drug, veterinary biological product, or biological product claimed in a patent or the use of which is claimed in a patent before the expiration of such patent."],[0,"(3) In any action for patent infringement brought under this section, no injunctive or other relief may be granted which would prohibit the making, using, offering to sell, or selling within the United States or importing into the United States of a patented invention under paragraph (1)."],[0,"(4) For an act of infringement described in paragraph (2)—"],[1,"(A) the court shall order the effective date of any approval of the drug or veterinary biological product involved in the infringement to be a date which is not earlier than the date of the expiration of the patent which has been infringed,"],[1,"(B) injunctive relief may be granted against an infringer to prevent the commercial manufacture, use, offer to sell, or sale within the United States or importation into the United States of an approved drug, veterinary biological product, or biological product,"],[1,"(C) damages or other monetary relief may be awarded against an infringer only if there has been commercial manufacture, use, offer to sell, or sale within the United States or importation into the United States of an approved drug, veterinary biological product, or biological product, and"],[1,"(D) the court shall order a permanent injunction prohibiting any infringement of the patent by the biological product involved in the infringement until a date which is not earlier than the date of the expiration of the patent that has been infringed under paragraph (2)(C), provided the patent is the subject of a final court decision, as defined in section 351(k)(6) of the Public Health Service Act, in an action for infringement of the patent under section 351(l)(6) of such Act, and the biological product has not yet been approved because of section 351(k)(7) of such Act."],[0,"The remedies prescribed by subparagraphs (A), (B), (C), and (D) are the only remedies which may be granted by a court for an act of infringement described in paragraph (2), except that a court may award attorney fees under section 285."],[0,"(5) Where a person has filed an application described in paragraph (2) that includes a certification under subsection (b)(2)(A)(iv) or (j)(2)(A)(vii)(IV) of section 505 of the Federal Food, Drug, and Cosmetic Act (21 U.S.C. 355), and neither the owner of the patent that is the subject of the certification nor the holder of the approved application under subsection (b) of such section for the drug that is claimed by the patent or a use of which is claimed by the patent brought an action for infringement of such patent before the expiration of 45 days after the date on which the notice given under subsection (b)(3) or (j)(2)(B) of such section was received, the courts of the United States shall, to the extent consistent with the Constitution, have subject matter jurisdiction in any action brought by such person under section 2201 of title 28 for a declaratory judgment that such patent is invalid or not infringed."],[0,"(6)(A) Subparagraph (B) applies, in lieu of paragraph (4), in the case of a patent—"],[1,"(i) that is identified, as applicable, in the list of patents described in section 351(l)(4) of the Public Health Service Act or the lists of patents described in section 351(l)(5)(B) of such Act with respect to a biological product; and"],[1,"(ii) for which an action for infringement of the patent with respect to the biological product—"],[2,"(I) was brought after the expiration of the 30-day period described in subparagraph (A) or (B), as applicable, of section 351(l)(6) of such Act; or"],[2,"(II) was brought before the expiration of the 30-day period described in subclause (I), but which was dismissed without prejudice or was not prosecuted to judgment in good faith."],[0,"(B) In an action for infringement of a patent described in subparagraph (A), the sole and exclusive remedy that may be granted by a court, upon a finding that the making, using, offering to sell, selling, or importation into the United States of the biological product that is the subject of the action infringed the patent, shall be a reasonable royalty."],[0,"(C) The owner of a patent that should have been included in the list described in section 351(l)(3)(A) of the Public Health Service Act, including as provided under section 351(l)(7) of such Act for a biological product, but was not timely included in such list, may not bring an action under this section for infringement of the patent with respect to the biological product."],[0,"(f)(1) Whoever without authority supplies or causes to be supplied in or from the United States all or a substantial portion of the components of a patented invention, where such components are uncombined in whole or in part, in such manner as to actively induce the combination of such components outside of the United States in a manner that would infringe the patent if such combination occurred within the United States, shall be liable as an infringer."],[0,"(2) Whoever without authority supplies or causes to be supplied in or from the United States any component of a patented invention that is especially made or especially adapted for use in the invention and not a staple article or commodity of commerce suitable for substantial noninfringing use, where such component is uncombined in whole or in part, knowing that such component is so made or adapted and intending that such component will be combined outside of the United States in a manner that would infringe the patent if such combination occurred within the United States, shall be liable as an infringer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/271?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§271. Infringement of patent","tname":"Patents","by":{"1":"2"}},{"t":"usc","label":"35 U.S.C. § 281","url":"https://www.law.cornell.edu/uscode/text/35/281","by":{"1":"2, 5, 39"}},{"t":"usc","label":"35 U.S.C. § 282","url":"https://www.law.cornell.edu/uscode/text/35/282","stext":{"head":"§282. Presumption of validity; defenses","paras":[[0,"(a) In General.—A patent shall be presumed valid. Each claim of a patent (whether in independent, dependent, or multiple dependent form) shall be presumed valid independently of the validity of other claims; dependent or multiple dependent claims shall be presumed valid even though dependent upon an invalid claim. The burden of establishing invalidity of a patent or any claim thereof shall rest on the party asserting such invalidity."],[0,"(b) Defenses.—The following shall be defenses in any action involving the validity or infringement of a patent and shall be pleaded:"],[1,"(1) Noninfringement, absence of liability for infringement or unenforceability."],[1,"(2) Invalidity of the patent or any claim in suit on any ground specified in part II as a condition for patentability."],[1,"(3) Invalidity of the patent or any claim in suit for failure to comply with—"],[2,"(A) any requirement of section 112, except that the failure to disclose the best mode shall not be a basis on which any claim of a patent may be canceled or held invalid or otherwise unenforceable; or"],[2,"(B) any requirement of section 251."],[1,"(4) Any other fact or act made a defense by this title."],[0,"(c) Notice of Actions; Actions During Extension of Patent Term.—In an action involving the validity or infringement of a patent the party asserting invalidity or noninfringement shall give notice in the pleadings or otherwise in writing to the adverse party at least thirty days before the trial, of the country, number, date, and name of the patentee of any patent, the title, date, and page numbers of any publication to be relied upon as anticipation of the patent in suit or, except in actions in the United States Court of Federal Claims, as showing the state of the art, and the name and address of any person who may be relied upon as the prior inventor or as having prior knowledge of or as having previously used or offered for sale the invention of the patent in suit. In the absence of such notice proof of the said matters may not be made at the trial except on such terms as the court requires. Invalidity of the extension of a patent term or any portion thereof under section 154(b) or 156 because of the material failure—"],[1,"(1) by the applicant for the extension, or"],[1,"(2) by the Director,"],[0,"to comply with the requirements of such section shall be a defense in any action involving the infringement of a patent during the period of the extension of its term and shall be pleaded. A due diligence determination under section 156(d)(2) is not subject to review in such an action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/282?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§282. Presumption of validity; defenses","tname":"Patents","by":{"1":"31"}},{"t":"usc","label":"35 U.S.C. § 296","url":"https://www.law.cornell.edu/uscode/text/35/296","subs":["(a)"],"op":1,"by":{"1":"11","2":"4"}},{"t":"usc","label":"35 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/35/307","subs":["(b)"],"by":{"1":"9, 22, 9, 22","2":"3"}},{"t":"usc","label":"35 U.S.C. § 317","url":"https://www.law.cornell.edu/uscode/text/35/317","subs":["(b)"],"ar":1,"by":{"1":"8, 22","2":"5, 6"}},{"t":"usc","label":"35 U.S.C. § 318","url":"https://www.law.cornell.edu/uscode/text/35/318","subs":["(c)"],"by":{"1":"8, 22, 8, 22","2":"3"}},{"t":"usc","label":"35 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/35/321","subs":["(a)","(b)"],"stext":{"head":"§321. Post-grant review","paras":[[0,"(a) In General.—Subject to the provisions of this chapter, a person who is not the owner of a patent may file with the Office a petition to institute a post-grant review of the patent. The Director shall establish, by regulation, fees to be paid by the person requesting the review, in such amounts as the Director determines to be reasonable, considering the aggregate costs of the post-grant review."],[0,"(b) Scope.—A petitioner in a post-grant review may request to cancel as unpatentable 1 or more claims of a patent on any ground that could be raised under paragraph (2) or (3) of section 282(b) (relating to invalidity of the patent or any claim)."],[0,"(c) Filing Deadline.—A petition for a post-grant review may only be filed not later than the date that is 9 months after the date of the grant of the patent or of the issuance of a reissue patent (as the case may be)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/321?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§321. Post-grant review","tname":"Patents","by":{"1":"8, 22, 37, 38, 37, 38"}},{"t":"usc","label":"35 U.S.C. § 325","url":"https://www.law.cornell.edu/uscode/text/35/325","subs":["(e)","(e)(1)","(e)(2)"],"by":{"1":"37, 38, 37, 38, 37, 38","2":"21"}},{"t":"usc","label":"35 U.S.C. § 327","url":"https://www.law.cornell.edu/uscode/text/35/327","subs":["(b)"],"by":{"1":"37, 38","2":"5, 6"}},{"t":"usc","label":"35 U.S.C. § 328","url":"https://www.law.cornell.edu/uscode/text/35/328","subs":["(c)"],"by":{"1":"37, 38, 37, 38"}},{"t":"law","label":"21st Century Department of Justice Appropriations Authorization Act, Pub. L. No. 107-273","url":"https://www.govinfo.gov/link/plaw/107/public/273","by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 46","url":"https://www.law.cornell.edu/uscode/text/28/46","subs":["(1946)"],"by":{"1":"36","2":"14"}},{"t":"usc","label":"28 U.S.C. § 1498","url":"https://www.law.cornell.edu/uscode/text/28/1498","subs":["(a)"],"stext":{"head":"§1498. Patent and copyright cases","paras":[[0,"(a) Whenever an invention described in and covered by a patent of the United States is used or manufactured by or for the United States without license of the owner thereof or lawful right to use or manufacture the same, the owner's remedy shall be by action against the United States in the United States Court of Federal Claims for the recovery of his reasonable and entire compensation for such use and manufacture. Reasonable and entire compensation shall include the owner's reasonable costs, including reasonable fees for expert witnesses and attorneys, in pursuing the action if the owner is an independent inventor, a nonprofit organization, or an entity that had no more than 500 employees at any time during the 5-year period preceding the use or manufacture of the patented invention by or for the United States. Nothwithstanding 1 the preceding sentences, unless the action has been pending for more than 10 years from the time of filing to the time that the owner applies for such costs and fees, reasonable and entire compensation shall not include such costs and fees if the court finds that the position of the United States was substantially justified or that special circumstances make an award unjust."],[0,"For the purposes of this section, the use or manufacture of an invention described in and covered by a patent of the United States by a contractor, a subcontractor, or any person, firm, or corporation for the Government and with the authorization or consent of the Government, shall be construed as use or manufacture for the United States."],[0,"The court shall not award compensation under this section if the claim is based on the use or manufacture by or for the United States of any article owned, leased, used by, or in the possession of the United States prior to July 1, 1918."],[0,"A Government employee shall have the right to bring suit against the Government under this section except where he was in a position to order, influence, or induce use of the invention by the Government. This section shall not confer a right of action on any patentee or any assignee of such patentee with respect to any invention discovered or invented by a person while in the employment or service of the United States, where the invention was related to the official functions of the employee, in cases in which such functions included research and development, or in the making of which Government time, materials or facilities were used."],[0,"(b) Hereafter, whenever the copyright in any work protected under the copyright laws of the United States shall be infringed by the United States, by a corporation owned or controlled by the United States, or by a contractor, subcontractor, or any person, firm, or corporation acting for the Government and with the authorization or consent of the Government, the exclusive action which may be brought for such infringement shall be an action by the copyright owner against the United States in the Court of Federal Claims for the recovery of his reasonable and entire compensation as damages for such infringement, including the minimum statutory damages as set forth in section 504(c) of title 17, United States Code: Provided, That a Government employee shall have a right of action against the Government under this subsection except where he was in a position to order, influence, or induce use of the copyrighted work by the Government: Provided, however, That this subsection shall not confer a right of action on any copyright owner or any assignee of such owner with respect to any copyrighted work prepared by a person while in the employment or service of the United States, where the copyrighted work was prepared as a part of the official functions of the employee, or in the preparation of which Government time, material, or facilities were used: And provided further, That before such action against the United States has been instituted the appropriate corporation owned or controlled by the United States or the head of the appropriate department or agency of the Government, as the case may be, is authorized to enter into an agreement with the copyright owner in full settlement and compromise for the damages accruing to him by reason of such infringement and to settle the claim administratively out of available appropriations."],[0,"Except as otherwise provided by law, no recovery shall be had for any infringement of a copyright covered by this subsection committed more than three years prior to the filing of the complaint or counterclaim for infringement in the action, except that the period between the date of receipt of a written claim for compensation by the Department or agency of the Government or corporation owned or controlled by the United States, as the case may be, having authority to settle such claim and the date of mailing by the Government of a notice to the claimant that his claim has been denied shall not be counted as a part of the three years, unless suit is brought before the last-mentioned date."],[0,"(c) The provisions of this section shall not apply to any claim arising in a foreign country."],[0,"(d) Hereafter, whenever a plant variety protected by a certificate of plant variety protection under the laws of the United States shall be infringed by the United States, by a corporation owned or controlled by the United States, or by a contractor, subcontractor, or any person, firm, or corporation acting for the Government, and with the authorization and consent of the Government, the exclusive remedy of the owner of such certificate shall be by action against the United States in the Court of Federal Claims for the recovery of his reasonable and entire compensation as damages for such infringement: Provided, That a Government employee shall have a right of action against the Government under this subsection except where he was in a position to order, influence, or induce use of the protected plant variety by the Government: Provided, however, That this subsection shall not confer a right of action on any certificate owner or any assignee of such owner with respect to any protected plant variety made by a person while in the employment or service of the United States, where such variety was prepared as a part of the official functions of the employee, or in the preparation of which Government time, material, or facilities were used: And provided further, That before such action against the United States has been instituted, the appropriate corporation owned or controlled by the United States or the head of the appropriate agency of the Government, as the case may be, is authorized to enter into an agreement with the certificate owner in full settlement and compromise, for the damages accrued to him by reason of such infringement and to settle the claim administratively out of available appropriations."],[0,"(e) Subsections (b) and (c) of this section apply to exclusive rights in mask works under chapter 9 of title 17, and to exclusive rights in designs under chapter 13 of title 17, to the same extent as such subsections apply to copyrights."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1498?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":2,"head":"§1498. Patent and copyright cases","tname":"Judiciary and Judicial Procedure","by":{"1":"5, 21, 10","2":"3, 16, 22, 3"}},{"t":"usc","label":"39 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/39/101","by":{"1":"10"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"33"}},{"t":"reg","label":"77 Fed. Reg. 48,680","url":"https://www.govinfo.gov/link/fr/77/48680","by":{"1":"9"}},{"t":"case","label":"Am. Innotek, Inc. v. United States","cite":"113 Fed. Cl. 668","y":2013,"url":"https://www.courtlistener.com/c/Fed.%20Cl./113/668/","by":{"2":"22"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Davis v. Pringle","cite":"268 U.S. 315","y":1925,"id":"scdb/1924-231","sc":1,"op":1,"ar":1,"sum":"Reasoning that “normal usages of speech” indicated that the Government was not a “person” entitled to priority under the Bankruptcy Act.","sumSrc":"opinion","by":{"2":"10, 11"}},{"t":"case","label":"Dollar Sav. Bank v. United States","cite":"86 U.S. 227","y":1873,"id":"scdb/1873-111","sc":1,"ar":1,"sum":"The United States brought an action of debt against The Dollar Savings Bank, in the court below, to recover certain internal revenue taxes, which the declaration alleged were due from it to the government. These taxes were asserted to have been authorized by an amendment contained in the ninth section of the Internal Revenue'Act of July 13th, 1866, by which part of a prior Internal Revenue Act, the act, namely, of …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"EmeraChem Holdings, LLC v. Volkswagen Grp. of Am., Inc.","cite":"859 F.3d 1341","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/859/1341/","by":{"2":"17"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"sum":"The Court found that the district court, rather than the Court of Appeals, has jurisdiction over \"mixed\" cases that have been dismissed by the Merit Systems Protection Board.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Racing Strollers, Inc. v. TRI Indus., Inc.","cite":"878 F.2d 1418","y":1989,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/878/1418/","sum":"Describing MPEP as “a looseleaf training and instruction manual for examiners” that contains “inconsistencies” and “does not have the force of law or [even] the force of the Patent Rules of Practice”.","sumSrc":"brief:2","by":{"2":"17"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"United States v. Midwest Oil Co.","cite":"236 U.S. 459","y":1915,"id":"scdb/1914-232","sc":1,"sum":"Prior to initiation of some right given by law, the citizen has no enforceable interest in the public statutes and no private right in land which is the property of the people.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"18, 19"}},{"t":"case","label":"Webster v. Fall","cite":"266 U.S. 507","y":1925,"id":"scdb/1924-066","sc":1,"sum":"1. A suit lacking a necessary party defendant should be dismissed' on that ground without deciding the merits.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"19"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(a)(1)"],"op":1,"by":{"2":"9"}},{"t":"usc","label":"35 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/35/2","subs":["(b)(11)"],"by":{"2":"6"}},{"t":"usc","label":"35 U.S.C. § 132","url":"https://www.law.cornell.edu/uscode/text/35/132","by":{"2":"13"}},{"t":"usc","label":"35 U.S.C. § 135","url":"https://www.law.cornell.edu/uscode/text/35/135","subs":["(e)"],"by":{"2":"5, 6"}},{"t":"usc","label":"35 U.S.C. § 257","url":"https://www.law.cornell.edu/uscode/text/35/257","subs":["(e)"],"by":{"2":"5"}},{"t":"usc","label":"35 U.S.C. § 292","url":"https://www.law.cornell.edu/uscode/text/35/292","subs":["(a)","(b)"],"by":{"2":"5, 6, 5, 6"}},{"t":"usc","label":"42 U.S.C. § 2182","url":"https://www.law.cornell.edu/uscode/text/42/2182","by":{"2":"15, 16"}},{"t":"usc","label":"51 U.S.C. § 20135","url":"https://www.law.cornell.edu/uscode/text/51/20135","subs":["(b)(2)"],"by":{"2":"15, 16"}}]};